package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class Phase6aPermissionGuardTest{private final AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);
 @Test void policyActionsAndAgencyScopeAreIndependent(){PerformancePolicyPermissionGuard guard=new PerformancePolicyPermissionGuard(client);when(client.resolve(eq(PerformancePolicyPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformancePolicyPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);}
 @Test void cycleFinalizeRequiresExactAction(){PerformanceCyclePermissionGuard guard=new PerformanceCyclePermissionGuard(client);when(client.resolve(eq(PerformanceCyclePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.FINALIZE,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformanceCyclePermissionGuard.FEATURE),anyString())).thenReturn(new EffectiveFeaturePermission("x",false,true,false,false,false,false,false,false,false,false,true,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.FINALIZE,"Bearer token")).doesNotThrowAnyException();}
 @Test void pmtActivationRequiresPublish(){PerformancePmtPermissionGuard guard=new PerformancePmtPermissionGuard(client);when(client.resolve(eq(PerformancePmtPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformancePmtPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).doesNotThrowAnyException();}
 @Test void ratingScalePublishAndAgencyScopeAreIndependent(){PerformanceRatingScalePermissionGuard guard=new PerformanceRatingScalePermissionGuard(client);when(client.resolve(eq(PerformanceRatingScalePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformanceRatingScalePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformanceRatingScalePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).doesNotThrowAnyException();}
 @Test void successIndicatorPublishRequiresIndependentAgencyWidePermission(){PerformanceSuccessIndicatorPermissionGuard guard=new PerformanceSuccessIndicatorPermissionGuard(client);when(client.resolve(eq(PerformanceSuccessIndicatorPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformanceSuccessIndicatorPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);}
 @Test void templatePublishRequiresIndependentAgencyWidePermission(){PerformanceTemplatePermissionGuard guard=new PerformanceTemplatePermissionGuard(client);when(client.resolve(eq(PerformanceTemplatePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformanceTemplatePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer token")).isInstanceOf(AccessDeniedException.class);}
 private static EffectiveFeaturePermission permission(boolean access,boolean add,boolean publish,PermissionDataScope scope){return new EffectiveFeaturePermission("x",false,access,add,true,false,publish,false,false,false,false,false,scope);}}
